var o=[{title:`Jak dlouho regenerace trvá`,text:`Závisí na cviku, celkovém objemu, intenzitě, spánku, kondici a tom, jak známá je práce. Po náročném tréninku velké svalové skupiny je běžným plánovacím vodítkem zhruba 48–72 hodin před dalším stejně náročným tréninkem. Je to vodítko a někteří lidé potřebují víc nebo míň.`},{title:`Známky, že jste se nezregenerovali`,text:`Bolest, která trvá déle než obvykle, méně opakování se stejnou zátěží, těžké nohy, nízká motivace a změny techniky mohou ukazovat na příliš velkou únavu. Jeden špatný trénink nedokazuje přetrénování. Hledejte trendy napříč několika tréninky, zejména spolu se špatným spánkem, nemocí nebo dalším stresem v ostatním životě.`},{title:`Rozložte náročnou práci`,text:`Typický týden může mít silový trénink celého těla v pondělí a čtvrtek, s lehkými procházkami v ostatní dny. Častější silový trénink může fungovat, když rozložíte cviky nebo svalové skupiny do týdne a objem držíte pod kontrolou. Lehké kardio nebo mobilita v den bez zvedání obvykle s regenerací dobře souzní.`},{title:`Pomozte tělu přizpůsobit se`,text:`Míříte na pravidelný spánek, dost jídla a vody, malá zvýšení tréninku a dny odpočinku, když je potřebujete. Bolest svalů není skóre toho, jak dobrý trénink byl. Pokud váš výkon stále klesá, snižte objem, zvolte snazší varianty nebo přidejte čas na regeneraci. Intenzitu nezvyšujte, abyste to vynahradili.`},{title:`Použití v TrainUp`,text:`Po každém tréninku ohodnoťte své úsilí a nahlaste jakoukoli bolest nebo nepohodlí. Když plán znovu vytvoříte, TrainUp se dívá na alespoň 3 tréninky. Jakákoli nedávná bolest znamená žádné zvýšení. Pokud byly 2 z vašich posledních 3 tréninků velmi těžké (RPE 9 nebo více) nebo dokončené z méně než 60 %, bude další plán lehčí. Historie ukazuje vaše průměrné úsilí a graf za 4 týdny. Pokud přetrvávají závažné příznaky, vyhledejte lékařskou radu.`}];var t=[{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: dávkování cvičení, regenerace a progrese`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`NHS: opožděná bolest svalů`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var a={sections:o,sources:t};export{a as default,o as sections,t as sources};